 for i in range(1,nc+1):
  pts=np.argwhere(labs==i);h=Counter(G[labs==i]).most_common(1)[0][0];clusters.append((pts,h))
 out=G.copy()
 for r,c in np.argwhere(G==wall):
  ds=[np.min(np.abs(pts-[r,c]).sum(axis=1)) for pts,h in clusters];md=min(ds);hs={clusters[j][1] for j,x in enumerate(ds) if x==md}
  if len(hs)==1:out[r,c]=next(iter(hs))
 for r in range(G.shape[0]-2):
  for c in range(G.shape[1]-2):
   if np.all(G[r:r+3,c:c+3]==wall):
    out[r:r+3,c:c+3]=wall;out[r+1,c+1]=Counter(G[marker].tolist()).most_common(1)[0][0]
 return out
